    <div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="55" aria-valuenow="0" id="bar"><span id="bar-fill"></span></div>
    <p class="progress-note" id="platinum-note">Platinum “Vice Got a Price!” unlocks when the other 54 are earned.</p>
  </div>
</header>

<nav class="tabs" aria-label="Views">
  <a href="#/" data-view="list" class="tab">Checklist</a>
  <a href="#/roadmap" data-view="roadmap" class="tab">Roadmap to Platinum</a>
